from __future__ import annotations; import shutil; import subprocess; from pathlib import Path; from textwrap import dedent; import yaml; from common.meta.extension import governance_report; from common.meta.extension.check_manifest import load_computed_concepts; ROOT = Path(__file__).resolve().parents[2]
def _write(path: Path, content: str='content\n') -> Path: path.parent.mkdir(parents=True, exist_ok=True); path.write_text(dedent(content).lstrip(), encoding='utf-8'); return path
_write_yaml = lambda path, payload: _write(path, yaml.safe_dump(payload, sort_keys=False)); _git = lambda repo, *args: subprocess.run(['git', '-C', str(repo), *args], check=True, capture_output=True, text=True).stdout.strip()
def _write_demo_contract(repo: Path, *, description: str, family: str | None, kind: str | None) -> None: _write(repo / 'common/demo/contract.py', f'\n        from common.meta.package_contract import ConceptRecord, PackageContract\n        CONTRACT = PackageContract(\n            name="demo", klass="domain", status="draft",\n            depends_on=[], interface=[], events=[], invariants=[], roadmap=[],\n            concepts=[ConceptRecord(\n                key="demo_concept", owner="common/demo/readme.md",\n                description={description!r}, family={family!r}, kind={kind!r},\n            )],\n        )\n        '); _write(repo / 'common/demo/__init__.py', ''); _write(repo / 'common/demo/readme.md', '# Demo\n')
def _seed_computed_registry_repo(tmp_path: Path, *, family: str | None, kind: str | None) -> tuple[Path, str]: repo = tmp_path / 'repo'; shutil.copytree(ROOT / 'common/meta', repo / 'common/meta', ignore=shutil.ignore_patterns('__pycache__', '*.pyc')); _write(repo / 'common/__init__.py', ''); _write(repo / 'common/meta/data/MANIFEST.yaml', '\n        concepts:\n          residual_concept:\n            owner: common/meta/readme.md\n            description: Residual concept remains shaped.\n            family: platform\n            kind: concept\n        '); _write_demo_contract(repo, description='Base package concept.', family=family, kind=kind); _git(repo, 'init', '-q'); _git(repo, 'config', 'user.email', 'governance-test@example.invalid'); _git(repo, 'config', 'user.name', 'Governance Test'); _git(repo, 'add', '.'); _git(repo, 'commit', '-qm', 'base'); return (repo, _git(repo, 'rev-parse', 'HEAD'))
def _source(report: dict[str, object], system: str) -> dict[str, object]: sources = report['sources']; assert isinstance(sources, list); return next((s for s in sources if s['system'] == system))
def test_AC14_1_12_report_covers_finance_manifest_shape(tmp_path: Path) -> None: 'AC-meta.ssot-governance.2'; [_write(tmp_path / rel) for rel in ('docs/ssot/accounting.md', 'docs/ssot/deployment.md', 'common/meta/data/migration-risk.yaml', 'docs/ssot/orphan.md', 'docs/ssot/schema.md', 'tools/check_deployment.py')]; _write(tmp_path / 'common/meta/data/MANIFEST.yaml', '\n        concepts:\n          decimal_rule:\n            owner: docs/ssot/accounting.md\n            description: Decimal monetary rule.\n          duplicate_decimal_rule:\n            owner: docs/ssot/accounting.md\n            description: Intentional duplicate.\n          migration_matrix:\n            owner: common/meta/data/migration-risk.yaml\n            description: Migration risk matrix.\n            kind: matrix\n            cross_refs: [docs/ssot/schema.md]\n          deployment_contract:\n            owner: docs/ssot/deployment.md\n            description: Deployment environment contract.\n            family: ops\n            kind: concept\n            cross_refs: [tools/check_deployment.py]\n          deployment_clause_without_parent:\n            owner: docs/ssot/deployment.md#clause\n            description: Explicit clause missing parent.\n            family: ops\n            kind: clause\n        '); report = governance_report.build_report(tmp_path); finance = _source(report, 'finance_report'); assert report['report_only'] is True and report['overall']['entry_count'] == 5; assert finance['entry_count'] == 5 and finance['owner_count'] == 4; assert finance['duplicate_owner_groups'] == [{'owner': 'docs/ssot/accounting.md', 'keys': ['decimal_rule', 'duplicate_decimal_rule']}]; assert finance['orphan_ssot_files'] == ['docs/ssot/orphan.md', 'docs/ssot/schema.md']; assert finance['machine_owner_entries']['missing_proof'] == ['migration_matrix']; markdown = governance_report.render_markdown(report); assert '| finance_report | 5 | 4 | 1 | 2 | 3 | 2 | 1 | 2 |' in markdown
def test_AC14_1_13_incremental_gate_only_blocks_changed_ssot_debt(tmp_path: Path) -> None: 'AC-meta.ssot-governance.3'; [_write(tmp_path / rel) for rel in ('docs/ssot/legacy-orphan.md', 'docs/ssot/new-orphan.md', 'docs/ssot/new-owned.md', 'docs/ssot/migration-risk.md', 'tests/tooling/test_new_owned.py', 'tests/tooling/test_migration_risk.py')]; _write(tmp_path / 'common/meta/data/MANIFEST.yaml', '\n        concepts:\n          legacy_without_family:\n            owner: docs/ssot/legacy-owned.md\n            description: Legacy entry remains report-only debt.\n          new_owned:\n            owner: docs/ssot/new-owned.md\n            description: New governed concept.\n            family: tdd\n            cross_refs: [tests/tooling/test_new_owned.py]\n          new_clause:\n            owner: docs/ssot/new-owned.md#clause\n            description: New clause with parent.\n            family: tdd\n            kind: clause\n            parent: new_owned\n          migration_risk:\n            owner: docs/ssot/migration-risk.md\n            description: Migration gate proof.\n            family: schema\n            cross_refs: [tests/tooling/test_migration_risk.py]\n          missing_family:\n            owner: docs/ssot/new-owned.md#missing-family\n            description: New scoreable concept missing family.\n          missing_parent:\n            owner: docs/ssot/new-owned.md#missing-parent\n            description: New clause missing parent.\n            family: tdd\n            kind: clause\n          high_risk_without_proof:\n            owner: docs/ssot/migration-risk.md#without-proof\n            description: Migration deployment secret policy.\n            family: schema\n        '); base_manifest = 'concepts:\n  legacy_without_family:\n    owner: docs/ssot/legacy-owned.md\n    description: Legacy entry.\n'; changed = ['common/meta/data/MANIFEST.yaml', 'docs/ssot/new-orphan.md', 'docs/ssot/new-owned.md', 'docs/ssot/migration-risk.md']; gate = governance_report.evaluate_incremental_gate(tmp_path, changed, base_manifest_texts={'finance_report': base_manifest}, include_infra2=False); pairs = {(v['code'], v['target']) for v in gate['violations']}; assert gate['enabled'] is True and gate['violation_count'] == 8; assert {('changed_ssot_file_without_owner', 'finance_report:docs/ssot/new-orphan.md'), ('new_manifest_entry_missing_family', 'finance_report:manifest:missing_family'), ('new_clause_missing_parent', 'finance_report:manifest:missing_parent'), ('changed_high_risk_entry_missing_proof', 'finance_report:manifest:high_risk_without_proof')} <= pairs; _write(tmp_path / 'common/meta/data/governance-exceptions.yaml', '\n        version: 1\n        exceptions:\n          - target: finance_report:manifest:missing_family\n            issue: https://github.com/wangzitian0/finance_report/issues/823\n            reason: Temporary fixture exception.\n            remove_when: The fixture replacement gate is active.\n        '); gate_exc = governance_report.evaluate_incremental_gate(tmp_path, changed, base_manifest_texts={'finance_report': base_manifest}, include_infra2=False); assert gate_exc['violation_count'] == gate['violation_count'] - 1 and gate_exc['exception_count'] == 1
def test_AC14_1_16_ssot_governance_ratios_cannot_regress(tmp_path: Path) -> None: 'AC-meta.ssot-governance.6'; [_write(tmp_path / rel) for rel in ('docs/ssot/shaped.md', 'docs/ssot/legacy-kind.md', 'docs/ssot/new-family-only.md', 'common/meta/data/migration-risk.yaml', 'docs/ssot/migration-risk-reviewed.yaml', 'tests/tooling/test_migration_risk.py')]; base_manifest = dedent('\n        concepts:\n          shaped: {owner: docs/ssot/shaped.md, description: Fully shaped., family: tdd, kind: concept}\n          legacy_kind_gap: {owner: docs/ssot/legacy-kind.md, description: Existing debt., family: tdd}\n          migration_reviewed: {owner: docs/ssot/migration-risk-reviewed.yaml, description: Reviewed., family: schema, kind: matrix, proofs: [tests/tooling/test_migration_risk.py]}\n          migration_unreviewed: {owner: common/meta/data/migration-risk.yaml, description: Unreviewed., family: schema, kind: matrix}\n        ').lstrip(); _write(tmp_path / 'common/meta/data/MANIFEST.yaml', base_manifest + '  new_family_only: {owner: docs/ssot/new-family-only.md, description: Lowers kind ratio., family: tdd}\n'); gate = governance_report.evaluate_incremental_gate(tmp_path, ['common/meta/data/MANIFEST.yaml', 'docs/ssot/new-family-only.md'], base_manifest_texts={'finance_report': base_manifest}, include_infra2=False); assert {(v['code'], v['target']) for v in gate['violations']} == {('governance_ratio_decreased', 'finance_report:ratio:manifest_kind_coverage'), ('governance_debt_increased', 'finance_report:debt:missing_kind')}
def test_AC_meta_ssot_governance_9_base_and_head_use_same_computed_concepts(tmp_path: Path) -> None: 'AC-meta.ssot-governance.9'; repo, base_ref = _seed_computed_registry_repo(tmp_path, family=None, kind=None); _write_demo_contract(repo, description='HEAD changes only the package concept description.', family=None, kind=None); gate = governance_report.evaluate_incremental_gate(repo, ['common/demo/contract.py'], base_ref=base_ref, include_infra2=False); assert gate['trend_check_count'] == 8 and gate['violation_count'] == 0
def test_AC14_1_14_finance_report_orphan_ssot_files_are_manifest_owned() -> None: 'AC-meta.ssot-governance.4'; report = governance_report.build_report(ROOT, include_infra2=False); finance = _source(report, 'finance_report'); assert report['overall']['errors'] == [] and finance['errors'] == [] and (finance['orphan_ssot_files'] == []); concepts = load_computed_concepts(ROOT, ROOT / 'common/meta/data/MANIFEST.yaml'); assert concepts['statement_parsing_model_selection_logging']['parent'] == 'observability_logging'; assert concepts['protection_count_floor']['parent'] == 'tdd_workflow'
